import React, { useState } from "react";
import axios from "axios";
import "../Styles/PostJob.css";

const PostJob = () => {
  const [jobData, setJobData] = useState({
    jobTitle: "",
    category: "",
    sector: "",
    rate: "",
    rateType: "",
    skills: "",
    description: "",
    payout: "",
  });

  const CATEGORIES = [
    "Design / Marketing",
    "Technology / IT",
    "Business / Finance",
    "Education / Training",
    "Logistics / Operations",
  ];

  const SECTORS = ["Private Company", "Government", "NGO", "Freelance"];

  const RATE_TYPES = ["Per Hour", "Per Task", "Per Day"];

  const handleChange = (e) => {
    setJobData({ ...jobData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const company = JSON.parse(localStorage.getItem("loggedUser"));
      if (!company) {
        alert("Please log in first.");
        return;
      }

      await axios.post("http://localhost:3001/addJob", {
        ...jobData,
        organization: company.companyName,
      });

      alert("Job posted successfully!");
      setJobData({
        jobTitle: "",
        category: "",
        sector: "",
        rate: "",
        rateType: "",
        skills: "",
        description: "",
        payout: "",
      });
    } catch (err) {
      console.error(err);
      alert("Failed to post job.");
    }
  };

  return (
    <div className="postjob-page">
      <h1 className="postjob-title">
        Post a <span className="accent">Job</span>
      </h1>

      <form className="postjob-form" onSubmit={handleSubmit}>
        <label>Job Title</label>
        <input
          type="text"
          name="jobTitle"
          value={jobData.jobTitle}
          onChange={handleChange}
          placeholder="Graphic Designer"
        />

        <div className="row">
          <div className="col">
            <label>Category</label>
            <select
              name="category"
              value={jobData.category}
              onChange={handleChange}
            >
              <option value="">Select category</option>
              {CATEGORIES.map((c) => (
                <option key={c} value={c}>
                  {c}
                </option>
              ))}
            </select>
          </div>

          <div className="col">
            <label>Sector</label>

            <div className="radio-group">
              {SECTORS.map((s) => (
                <label key={s} className="radio-option">
                  <input
                    type="radio"
                    name="sector"
                    value={s}
                    checked={jobData.sector === s}
                    onChange={handleChange}
                  />
                  {s}
                </label>
              ))}
            </div>
          </div>
        </div>

        <div className="row">
          <div className="col">
            <label>Rate (OMR)</label>
            <input
              type="number"
              name="rate"
              value={jobData.rate}
              onChange={handleChange}
              placeholder="10"
            />
          </div>

          <div className="col">
            <label>Rate Type</label>
            <select
              name="rateType"
              value={jobData.rateType}
              onChange={handleChange}
            >
              <option value="">Select type</option>
              {RATE_TYPES.map((r) => (
                <option key={r} value={r}>
                  {r}
                </option>
              ))}
            </select>
          </div>
        </div>

        <label>Skills Required</label>
        <input
          type="text"
          name="skills"
          value={jobData.skills}
          onChange={handleChange}
          placeholder="Photoshop, Canva, Social Media"
        />

        <label>Description</label>
        <textarea
          name="description"
          value={jobData.description}
          onChange={handleChange}
          placeholder="Explain job responsibilities and requirements"
        />

        <label>Payout (optional)</label>
        <input
          type="text"
          name="payout"
          value={jobData.payout}
          onChange={handleChange}
          placeholder="e.g. After project completion"
        />

        <div className="btn-area">
          <button type="submit" className="btn-post">
            Post Job
          </button>
          <button
            type="button"
            className="btn-clear"
            onClick={() =>
              setJobData({
                jobTitle: "",
                category: "",
                sector: "",
                rate: "",
                rateType: "",
                skills: "",
                description: "",
                payout: "",
              })
            }
          >
            Clear
          </button>
        </div>
      </form>
    </div>
  );
};

export default PostJob;
